using System.IO;
using System.Text.Json;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using VisionCore;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.Calibration;
public static class NImageModuleChecks{
 public static int Run(){int checks=0;void Check(bool pass,string message){checks++;if(!pass)throw new Exception(message);}var plugin=new NImagePlugin();var registry=new ModuleRegistry();registry.Register(plugin.Descriptor,plugin.CreateRuntime);Check(plugin.Descriptor.Outputs.Count==38,"37 original output fields plus explicit independent CalibData contract");Check(plugin.PointInputAliases.SequenceEqual(new[]{new ToolPointInputAlias("PhyPoint","MovePhysicalPointX","MovePhysicalPointY"),new("Image Point","PicPointX","PicPointY"),new("Physical Point","PhysicalPointX","PhysicalPointY")}),"Source XML combination aliases consume common point binding service");using var solution=new ModuleExecutionScope();var a=solution.ForProcedure("A");var b=solution.ForProcedure("B");var values=NImageParameters.Defaults();values["RotPointTotalNum"]=JsonSerializer.SerializeToElement(0);var runtime=plugin.CreateRuntime();var path=Path.GetFullPath("tests/NImageCalibration.PluginChecks/Fixtures/hik-i-help-derived.png");var decoder=BitmapDecoder.Create(new Uri(path),BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);var gray=new FormatConvertedBitmap(decoder.Frames[0],PixelFormats.Gray8,null,0);int width=gray.PixelWidth,height=gray.PixelHeight;var bytes=new byte[width*height];gray.CopyPixels(bytes,width,0);GrayImage Shift(int index){int dx=index%3*10,dy=index/3*10;var data=Enumerable.Repeat((byte)255,bytes.Length).ToArray();for(int y=0;y<height-dy;y++)bytes.AsSpan(y*width,width-dx).CopyTo(data.AsSpan((y+dy)*width+dx,width-dx));return new(width,height,data);}
  ModuleExecutionContext Context(int index,ModuleExecutionScope scope)=>new("same-node",Directory.GetCurrentDirectory(),new Dictionary<string,PortValue>{{"InputImage",PortValue.Image(Shift(index))},{"MovePhysicalPointX",PortValue.Number(index%3)},{"MovePhysicalPointY",PortValue.Number(index/3)},{"RotateAngle",PortValue.Number(0)}},values){Scope=scope,ProcedureId=scope.ProcedureId};
  ToolEditorContext Editor(ModuleExecutionScope scope)=>new(new("same-node",NImagePlugin.Id,"1.0.0","N图像标定",values),Directory.GetCurrentDirectory(),next=>values=next,_=>throw new InvalidOperationException()){Scope=scope};
  ModuleResult? last=null;var records=new List<object>();for(int i=0;i<9;i++){last=runtime.ExecuteAsync(Context(i,a),default).GetAwaiter().GetResult();Check(last.Status==ModuleStatus.Success,"Real pixel batch execution "+i+": "+last.Message);Check(last.Outputs["CurNum"].As<long>()==i+1,"Original frame count");Check(last.Outputs["CalibStatus"].As<long>()==(i==8?1:0),"No invented early calibration success");if(i<8)Check(!last.Outputs.ContainsKey("CalibData")&&last.Outputs["OutImagePointX"].As<IReadOnlyList<double>>().SequenceEqual(new[]{0d}),"Source incomplete zero placeholder without stale matrix");records.Add(new{frame=i,status=last.Status.ToString(),scalars=last.Outputs.Where(p=>p.Value.Kind is DataKind.Number or DataKind.Integer).ToDictionary(p=>p.Key,p=>p.Value.Value)});}
  Check(last!.Outputs["CornerPairsNum"].As<long>()==168,"Actual independent pixel detector finds original common corners");Check(last.Outputs["OutImagePointX"].As<IReadOnlyList<double>>().Count==9&&last.Outputs["OutImagePointY"].As<IReadOnlyList<double>>().Count==9,"Module outputs first corner across frames, not all 168 corners");var matrix=last.Outputs["CalibData"].As<CalibrationData>().ImageToWorld;Check(matrix.Count==9&&Math.Abs(matrix[0]-.1)<.005&&Math.Abs(matrix[4]-.1)<.005,"Real detected pixels reach calibration solve");
  string directory="analysis/full-audit/n-image-calibration/module-runtime";Directory.CreateDirectory(directory);string export=Path.GetFullPath(Path.Combine(directory,"independent-calibration.xml"));plugin.Export(Editor(a),export);var file=NImageFile.Read(new StringReader(File.ReadAllText(export)));Check(file.TranslationCount==9&&file.RotationCount==0&&file.ImagePoints.Count==9,"Real solve exports module CalibInfo data");Check(file.Matrix.Zip(matrix).All(p=>Math.Abs(p.First-p.Second)<1e-5),"File and runtime typed matrix agree");Check(file.RotationDirection==-999&&file.RotationError==-999,"File no-rotation sentinel differs from zero scalar runtime outputs");
  var display=plugin.LastDisplay(Editor(a).Node,Directory.GetCurrentDirectory(),a);Check(display?.Image!=null&&display.Graphics.Any(g=>g.Type=="path"&&g.Points.Count==9),"Original Display.xml trajectory uses common production graphics projector");
  var second=runtime.ExecuteAsync(Context(0,b),default).GetAwaiter().GetResult();Check(second.Outputs["CurNum"].As<long>()==1&&plugin.Inspect(Editor(a)).Current==9,"Same node ID in second procedure owns separate image batch");var restart=runtime.ExecuteAsync(Context(0,a),default).GetAwaiter().GetResult();Check(restart.Outputs["CurNum"].As<long>()==1&&restart.Outputs["CalibStatus"].As<long>()==0&&!restart.Outputs.ContainsKey("CalibData"),"Next frame after full batch resets and invalidates old solve");try{plugin.Export(Editor(a),export);throw new Exception("Stale calibration exported");}catch(InvalidOperationException){checks++;}
  plugin.Clear(Editor(a));Check(plugin.Inspect(Editor(a)).Current==0&&plugin.Inspect(Editor(b)).Current==1,"Clear only affects owning procedure");values["HomoFixEnable"]=JsonSerializer.SerializeToElement(true);var missingFix=runtime.ExecuteAsync(Context(0,a),default).GetAwaiter().GetResult();Check(missingFix.NativeErrorCode==0xe000031c&&plugin.Inspect(Editor(a)).Current==0,"Missing fix point fails before image capture");using var cancellation=new CancellationTokenSource();cancellation.Cancel();try{runtime.ExecuteAsync(Context(0,a),cancellation.Token);throw new Exception("Cancellation ignored");}catch(OperationCanceledException){checks++;}Check(plugin.Inspect(Editor(a)).Current==0,"Pre-capture cancellation retains empty state");
  string automatic=Path.GetFullPath(Path.Combine(directory,"automatic-fixed-"+Guid.NewGuid().ToString("N")+".xml"));values["RefreshFileEnable"]=JsonSerializer.SerializeToElement(true);values["CalibPathName"]=JsonSerializer.SerializeToElement(automatic);values["CalibPointTotalNum"]=JsonSerializer.SerializeToElement(4);using var fixScope=new ModuleExecutionScope();var fixedProcedure=fixScope.ForProcedure("fixed");RgbImage Colored(GrayImage source){var rgb=new byte[source.Width*source.Height*3];for(int j=0;j<source.Pixels.Length;j++){int v=source.Pixels[j];rgb[3*j]=(byte)(20+235*v/255);rgb[3*j+1]=(byte)(80+175*v/255);rgb[3*j+2]=(byte)(140+115*v/255);}return new(source.Width,source.Height,rgb);}ModuleResult? fixedResult=null;foreach(int i in new[]{0,1,3,4}){var original=Context(i,fixedProcedure);var inputs=original.Inputs.ToDictionary(p=>p.Key,p=>p.Value);inputs["InputImage"]=PortValue.Image(Colored(inputs["InputImage"].As<GrayImage>()));inputs["Image Point"]=PortValue.Point(new Point2(100,200));inputs["Physical Point"]=PortValue.Point(new Point2(7,11));fixedResult=runtime.ExecuteAsync(new ModuleExecutionContext("same-node",Directory.GetCurrentDirectory(),inputs,values){Scope=fixedProcedure,ProcedureId=fixedProcedure.ProcedureId},default).GetAwaiter().GetResult();Check(fixedResult.Status==ModuleStatus.Success,"HomoFix actual image execution "+i+": "+fixedResult.Message);}var fixedMatrix=fixedResult!.Outputs["CalibData"].As<CalibrationData>().ImageToWorld;double denominator=fixedMatrix[6]*100+fixedMatrix[7]*200+fixedMatrix[8];Check(Math.Abs((fixedMatrix[0]*100+fixedMatrix[1]*200+fixedMatrix[2])/denominator-7)<1e-4&&Math.Abs((fixedMatrix[3]*100+fixedMatrix[4]*200+fixedMatrix[5])/denominator-11)<1e-4,"Production bound compound points apply original homography correction");
  using var referenceScope=new ModuleExecutionScope();var monoProcedure=referenceScope.ForProcedure("mono-reference");ModuleResult? monoResult=null;foreach(int i in new[]{0,1,3,4}){var inputs=Context(i,monoProcedure).Inputs.ToDictionary(p=>p.Key,p=>p.Value);inputs["InputImage"]=PortValue.Image(ImageColorConversion.ToMono8(Colored(inputs["InputImage"].As<GrayImage>())));inputs["Image Point"]=PortValue.Point(new Point2(100,200));inputs["Physical Point"]=PortValue.Point(new Point2(7,11));monoResult=runtime.ExecuteAsync(new ModuleExecutionContext("same-node",Directory.GetCurrentDirectory(),inputs,values){Scope=monoProcedure,ProcedureId=monoProcedure.ProcedureId},default).GetAwaiter().GetResult();Check(monoResult.Status==ModuleStatus.Success,"Colored equivalent Mono actual execution "+i);}Check(monoResult!.Outputs["CalibData"].As<CalibrationData>().ImageToWorld.SequenceEqual(fixedMatrix),"Actual product RGB and explicit equivalent Mono batches yield identical calibration matrix");
  Check(File.Exists(automatic),"Production RefreshFileEnable saves upon actual batch completion");var automaticFile=NImageFile.Read(new StringReader(File.ReadAllText(automatic)));Check(automaticFile.Matrix.Zip(fixedMatrix).All(p=>Math.Abs(p.First-p.Second)<1e-5),"Automatic file exports corrected matrix");
  File.WriteAllText(Path.Combine(directory,"verification.json"),JsonSerializer.Serialize(new{checks,records,matrix,manualAccepted=false,originalPlatformReplay=false,scope="Production NImagePlugin actual owned image/recognition/solve/export/display/scoped lifecycle; synthetic help-derived pixels, no devices"},new JsonSerializerOptions{WriteIndented=true}));return checks;
 }
